starterCodeJson.code:
// Report 5.3 — System Test. One object per test-case row; "workflow" = the sheet it belongs to.
// steps: { as: 'student1' | 'student2' | 'student3' | 'manager' | 'admin' | 'guest', call: 'METHOD /path', body?, expect?: { status, body } }
const TEST_CASES = [
  {
    id: 'SB-1',
    workflow: 'StudentBooking',
    description: 'Verify the main journey: view labs, book a seat, see it in My Bookings, cancel it',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'guest',
        call: 'GET /api/labs',
        expect: { status: 200, body: { '0': { code: 'LAB01', status: 'OPEN' }, length: 3 } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 14, duration: 2 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0001', status: 'CONFIRMED' }, length: 1 } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0001', status: 'CANCELLED' } } },
      },
    ],
  },
];

// Test Statistics sheet (Report 5.3)
const STATS = {
  passed: 0, failed: 0, pending: 0, na: 0, total: 0,
  testCoverage: 0,        // (Passed + Failed) × 100 / (Total − N/A), 2 decimals
  successfulCoverage: 0,  // Passed × 100 / (Total − N/A), 2 decimals
  reportRound: 0,         // which round a FINAL report should show
};

