// Report 5.3 — System Test: 4 workflow sheets, 14 cases, 3 roles.
const TEST_CASES = [
  {
    id: 'SB-1',
    workflow: 'StudentBooking',
    description: 'Verify the main journey: view labs, book a seat, see it in My Bookings, cancel it',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'guest',
        call: 'GET /api/labs',
        expect: { status: 200, body: { '0': { code: 'LAB01', status: 'OPEN' }, length: 3 } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 14, duration: 2 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0001', status: 'CONFIRMED' }, length: 1 } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0001', status: 'CANCELLED' } } },
      },
    ],
  },
  {
    id: 'SB-2',
    workflow: 'StudentBooking',
    description: 'Verify that a booking for today must start at least one hour from now (08:00 rejected, 09:00 accepted)',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 8, duration: 1 },
        expect: { status: 422, body: { error: 'TOO_SOON' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
    ],
  },
  {
    id: 'SB-3',
    workflow: 'StudentBooking',
    description: 'Verify the 14-day booking window (day 14 accepted, day 15 and yesterday rejected)',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-16', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-17', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'OUT_OF_WINDOW' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-01', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'OUT_OF_WINDOW' } },
      },
    ],
  },
  {
    id: 'SB-4',
    workflow: 'StudentBooking',
    description: 'Verify that a booking must end by 21:00 (18:00 + 3 h accepted, 19:00 + 3 h rejected)',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 18, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 19, duration: 3 },
        expect: { status: 422, body: { error: 'AFTER_CLOSING' } },
      },
    ],
  },
  {
    id: 'SB-5',
    workflow: 'StudentBooking',
    description: 'Verify the 2-hour cancellation deadline (09:00 today too late, 10:00 today still allowed)',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 9, duration: 1 },
        expect: { status: 201, body: { code: 'BK0001' } },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 10, duration: 1 },
        expect: { status: 201, body: { code: 'BK0002' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 409, body: { error: 'TOO_LATE' } } },
      { as: 'student1', call: 'DELETE /api/bookings/BK0002', expect: { status: 200, body: { status: 'CANCELLED' } } },
    ],
  },
  {
    id: 'SB-6',
    workflow: 'StudentBooking',
    description: 'Verify that cancelled hours are not counted in the weekly 6-hour limit',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 3 },
        expect: { status: 201, body: { code: 'BK0002' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0002', expect: { status: 200 } },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-05', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-06', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'WEEKLY_LIMIT' } },
      },
    ],
  },
  {
    id: 'SB-7',
    workflow: 'StudentBooking',
    description: 'Verify that only the owner can cancel, and only once',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 201, body: { code: 'BK0001' } },
      },
      { as: 'student2', call: 'DELETE /api/bookings/BK0001', expect: { status: 403, body: { error: 'NOT_OWNER' } } },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200 } },
      {
        as: 'student1',
        call: 'DELETE /api/bookings/BK0001',
        expect: { status: 409, body: { error: 'ALREADY_CANCELLED' } },
      },
    ],
  },
  {
    id: 'WL-1',
    workflow: 'Waitlist',
    description: 'Verify that the waitlist is promoted first come, first served when the seat is released',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { code: 'BK0002', status: 'PENDING' } },
      },
      {
        as: 'student3',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-03', startHour: 10, duration: 2 },
        expect: { status: 201, body: { code: 'BK0003', status: 'PENDING' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200 } },
      {
        as: 'student2',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0002', status: 'CONFIRMED' } } },
      },
      {
        as: 'student3',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: { '0': { code: 'BK0003', status: 'PENDING' } } },
      },
    ],
  },
  {
    id: 'WL-2',
    workflow: 'Waitlist',
    description: 'Verify that the promoted student receives a "Booking confirmed" e-mail',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-05', startHour: 15, duration: 1 },
        expect: { status: 201 },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-05', startHour: 15, duration: 1 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200 } },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: {
          status: 200,
          body: {
            '1': { to: 'binh@fpt.edu.vn', subject: 'Added to waitlist' },
            '2': { to: 'binh@fpt.edu.vn', subject: 'Booking confirmed' },
            length: 3,
          },
        },
      },
    ],
  },
  {
    id: 'LC-1',
    workflow: 'LabClosure',
    description: 'Verify that closing a lab cancels the students’ bookings and blocks new ones',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 2 },
        expect: { status: 201 },
      },
      {
        as: 'manager',
        call: 'PATCH /api/labs/LAB01',
        body: { status: 'CLOSED' },
        expect: { status: 200, body: { status: 'CLOSED', cancelled: 1 } },
      },
      { as: 'student1', call: 'GET /api/bookings/me', expect: { status: 200, body: { '0': { status: 'CANCELLED' } } } },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 409, body: { error: 'LAB_CLOSED' } },
      },
    ],
  },
  {
    id: 'LC-2',
    workflow: 'LabClosure',
    description: 'Verify that a lab re-opened by the manager accepts bookings again',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'manager',
        call: 'PATCH /api/labs/LAB03',
        body: { status: 'OPEN' },
        expect: { status: 200, body: { status: 'OPEN' } },
      },
      { as: 'guest', call: 'GET /api/labs', expect: { status: 200, body: { '2': { code: 'LAB03', status: 'OPEN' } } } },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB03', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
    ],
  },
  {
    id: 'LC-3',
    workflow: 'LabClosure',
    description: 'Verify that the lab closed in the seed data refuses bookings',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB03', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 409, body: { error: 'LAB_CLOSED' } },
      },
    ],
  },
  {
    id: 'AS-1',
    workflow: 'AccountSecurity',
    description: 'Verify that an account locked by the admin loses its session at once and works again after unlock',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-03', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      { as: 'admin', call: 'POST /api/admin/users/an@fpt.edu.vn/lock', expect: { status: 200, body: { locked: true } } },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 401, body: { error: 'UNAUTHENTICATED' } },
      },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 423, body: { error: 'ACCOUNT_LOCKED' } },
      },
      {
        as: 'admin',
        call: 'POST /api/admin/users/an@fpt.edu.vn/unlock',
        expect: { status: 200, body: { locked: false } },
      },
      {
        call: 'POST /api/auth/login',
        body: { email: 'an@fpt.edu.vn', password: 'An@12345' },
        expect: { status: 200, body: { role: 'STUDENT' } },
      },
    ],
  },
  {
    id: 'AS-2',
    workflow: 'AccountSecurity',
    description: 'Verify that three wrong passwords lock the account until the admin unlocks it',
    precondition: 'System running with seed data; clock Mon 2026-11-02 08:00',
    steps: [
      { call: 'POST /api/auth/login', body: { email: 'binh@fpt.edu.vn', password: 'x1' }, expect: { status: 401 } },
      { call: 'POST /api/auth/login', body: { email: 'binh@fpt.edu.vn', password: 'x2' }, expect: { status: 401 } },
      { call: 'POST /api/auth/login', body: { email: 'binh@fpt.edu.vn', password: 'x3' }, expect: { status: 401 } },
      {
        call: 'POST /api/auth/login',
        body: { email: 'binh@fpt.edu.vn', password: 'Binh@123' },
        expect: { status: 423, body: { error: 'ACCOUNT_LOCKED' } },
      },
      { as: 'admin', call: 'POST /api/admin/users/binh@fpt.edu.vn/unlock', expect: { status: 200 } },
      {
        call: 'POST /api/auth/login',
        body: { email: 'binh@fpt.edu.vn', password: 'Binh@123' },
        expect: { status: 200 },
      },
    ],
  },
];

// Test Statistics sheet (Report 5.3) — Round 3 (the latest) of the four sheets. Applicable = 40 − 4 = 36.
const STATS = {
  passed: 32,                // 14 + 6 + 7 + 5
  failed: 2,                 // 1 + 1 + 0 + 0
  pending: 2,                // 0 + 1 + 1 + 0
  na: 4,                     // 1 + 0 + 2 + 1
  total: 40,                 // 16 + 8 + 10 + 6
  testCoverage: 94.44,       // 34 × 100 / 36
  successfulCoverage: 88.89, // 32 × 100 / 36
  reportRound: 3,            // a final report shows the LATEST round (link B8…E8, say so in Notes)
};

